          "comment": "10yo who has produced the odd fair performance this year but is winless since October 2023",
          "spotlight": "10yo who had produced the odd fair performance this year but has been soundly beaten the last twice and is winless since October 2023.",
          "quotes": [
            {
              "date": "2023-10-20",
              "horse": "John Kirkup",
              "horse_id": "hrs_10303090",
              "race": "Sam Hall Memorial Handicap",
              "race_id": "rac_11045008",
              "course": "Redcar",
              "course_id": "crs_1222",
              "distance_f": "5",
              "distance_y": "1100",
              "quote": "John Kirkup was due a win as he's been unlucky all season. He got his ground and he always shows his best - David Thompson, trainer."
            },
            {
              "date": "2020-10-19",
              "horse": "John Kirkup",
              "horse_id": "hrs_10303090",
              "race": "Visit goracinginyorkshire.com Handicap",
              "race_id": "rac_9973782",
              "course": "Pontefract",
              "course_id": "crs_1196",
              "distance_f": "5",
              "distance_y": "1103",
              "quote": "John Kirkup loves these conditions and it was a good idea to drop him back to five furlongs on this stiff track. He travelled into it well and got the splits at the right time - Connor Beasley, rider."
            },
            {
              "date": "2017-08-04",
              "horse": "John Kirkup",
              "horse_id": "hrs_10303090",
              "race": "Tomrods Steel Stockholders Nursery Handicap",
              "race_id": "rac_8847176",
              "course": "Thirsk",
              "course_id": "crs_2080",
              "distance_f": "5",
              "distance_y": "1100",
              "quote": "John Kirkup could be one for the Two-Year-Old Trophy at Redcar and he's likely to run in another nursery before then. He can go over five or six furlongs but wants give in the ground - Michael Dods, trainer."
            },
            {
              "date": "2017-06-28",
              "horse": "John Kirkup",
              "horse_id": "hrs_10303090",
              "race": "Edmundson Cabletech Carlisle Novice Auction Stakes",
              "race_id": "rac_8807786",
              "course": "Carlisle",
              "course_id": "crs_208",
              "distance_f": "5",
              "distance_y": "1100",
              "quote": "John Kirkup got shuffled back and to finish like he has is a fair effort particularly with his penalty. He won't run without a bit of cut in the ground - Michael Dods, trainer."
            },
            {
              "date": "2017-06-09",
              "horse": "John Kirkup",
              "horse_id": "hrs_10303090",
              "race": "Racing UK In HD Novice Stakes",
              "race_id": "rac_8787948",
              "course": "Carlisle",
              "course_id": "crs_208",
              "distance_f": "5",
              "distance_y": "1100",
              "quote": "John Kirkup ran with the choke out first time at Ayr and we've brought him back to a stiff five furlongs and got him behind horses and he's dropped his head. He's quite a nice horse and has done it nicely on ground he has enjoyed - Michael Dods, trainer."
            }
          ],
          "stable_tour": [
            {
              "quote": "Another old warrior with a decent wins to runs ratio and he goes particularly well for Connor Beasley. The thing with John is that you can not have the ground soft enough for him. We took a gamble running him at Ayr last month as the rains were forecast, thankfully it arrived and he won for the eighth time. However, last time out at Thirsk it was good ground which is too quick for him. 10-08-21"
            }
          ],
