          "comment": "Yet to match 2yo best this year but this is considerably easier than Chester last month",
          "spotlight": "Promise as a 2yo; attracted support on his reappearance but left the impression the run may have been needed; well beaten last time but that was in a good 0-75 at Chester; has a bit to prove but this drop into 0-55 company will make life easier and he's not dismissed.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "We've only got five or six juveniles. He's the one who's the most forward, the rest are a little bit slow to come to hand. He was fifth the other day when topweight in a nursery at Leicester behind Tees Aggregates. He ran okay but the ground was probably a bit quick for him. He's been fourth a couple of two-year-old before the season's end.times too and I'm pretty sure he'll win as a 07-08-24"
            }
          ],
