              "distance_f": "12",
              "distance_y": "2640",
              "quote": "Cogital usually runs over further, so I didn't want it to turn into a sprint and wanted to use his stamina up the straight. He's a lovely horse to be fair and ran well last time at Ascot. He was unlucky then and should have been a lot closer. I imagine he'll mix and match with the Flat and jumping - Jordan Williams, rider."
