          "comment": "Nine-race maiden under both codes and he's finished in rear back on Flat in last two runs",
          "spotlight": "Ex-Irish gelding; still a maiden after nine starts under both codes and he's finished in rear back on the Flat (1m2f/1m4f; Polytrack) in last two runs; now takes a big drop back in grade but he needs to raise his game.",
