            {
              "quote": "He was bought as a dual-purpose horse and ran a nice race when second last time at Plumpton. He could pinch a little maiden and we'll see what there is around Easter. He'll qualify for a mark after his next run. He's no world-beater but I think he's going to be a good, fun horse over hurdles and on the Flat. 26-02-25"
            }
