          "comment": "Eyecatcher in a C&D maiden last month and needs a close look on handicap debut",
          "spotlight": "Well held at big prices in three qualifying runs but she ran into some trouble before making some eyecatching late headway in a C&D maiden (fifth of 11) last month; that was behind some useful rivals and she needs a close look now switched to a handicap.",
