          "comment": "Pulled up early over C&D six weeks ago but went close over C&D 13 days previously",
          "spotlight": "10yo who ran without front shoe and was pulled up early over C&D six weeks ago; however, 13 days earlier he went close over C&D following an absence, and is not written off today.",
          "quotes": [
            {
              "date": "2019-03-19",
              "horse": "Capone",
              "horse_id": "hrs_14616238",
              "race": "MansionBet Handicap Hurdle",
              "race_id": "rac_9398805",
              "course": "Huntingdon",
              "course_id": "crs_676",
              "distance_f": "16",
              "distance_y": "3471",
              "quote": "That was a disaster. I left the ear plugs in and Noel said Capone never woke up. He's going to be a much nicer horse next year and it's great to give Noel a winner - Charlie Mann, trainer."
            },
            {
              "date": "2019-01-03",
              "horse": "Capone",
              "horse_id": "hrs_14616238",
              "race": "Best Wishes For 2019 Juvenile Hurdle",
              "race_id": "rac_9336470",
              "course": "Ludlow",
              "course_id": "crs_884",
              "distance_f": "16",
              "distance_y": "3469",
              "quote": "Noel (Fehily) thinks I ran Capone too soon as he didn't settle today but he's a lot better than that. He won't run again for at least a month but he's a decent horse. He works very well and we've got nothing that can go with him at home - Charlie Mann, trainer."
            }
          ],
          "stable_tour": [
            {
              "quote": "He was a present from Charlie Mann when he retired. He's had a wonderful season but sadly he irritated an old leg injury when I ran him at Salisbury the other day. He couldn't get into the race on the rail and when he got clear he stretched and I think he did something funny when he crossed the road, so we won't see him in a little while. 21-09-23"
            }
          ],
