          "comment": "Progressive last year, made a bright start to the new season over this trip at Navan",
          "spotlight": "Improved sort last year, winning three times, including over this trip at Listowel (yielding) final start; made a bright start to the season when fourth of 21 in a handicap over this trip at Navan a month ago.",
