          "comment": "Ended last season's Flat campaign with back-to-back wins, two hurdle wins since, respected",
          "spotlight": "Has won two of his five starts over hurdles since signing off last season's Flat campaign with back-to-back wins at Down Royal and Thurles; proved himself as a thorough stayer over hurdles with victory over a near-3m trip at Punchestown last time; this could be close to his optimum on the Flat.",
