          "comment": "Useful form in stake races last year, has failed to reach the same level in two 2025 runs",
          "spotlight": "Campaigned in good company last year after a 1m4f Bellewstown maiden win; not beaten far in a Group 3 race at Deauville and similar in a Listed race at Longhamp before 5l second in a 1m4f Group 3 at Newmarket; has failed to reach the same level in two runs this term.",
