          "comment": "Second three times this year, closely matched with Lemsairbat on Cork running, stays well",
          "spotlight": "Won a 1m6f Gowran Listed race for Shark Hanlon last year; three-time runner-up this season, including behind the now-retired star Kyprios at Navan and when going close in a 2m Group event in Germany; another solid display when dropped to 1m4f at Cork; nothing between her and Lemsairbat on that running.",
          "quotes": [
            {
              "date": "2023-08-05",
              "horse": "Enfranchise",
              "horse_id": "hrs_24456236",
              "race": "BoyleSports Download Our App Maiden Hurdle",
              "race_id": "rac_11005813",
              "course": "Galway",
              "course_id": "crs_4758",
              "distance_f": "17",
              "distance_y": "3695",
              "quote": "Enfranchise had a run here during the week and it made a big difference. I think she's very smart. I have her entered in the Ebor but she might not get in - Shark Hanlon, trainer."
            },
            {
              "date": "2022-06-19",
              "horse": "Enfranchise",
              "horse_id": "hrs_24456236",
              "race": "Sky Bet Sunday Series Middle-Distance Handicap",
              "race_id": "rac_10565490",
              "course": "Pontefract",
              "course_id": "crs_1196",
              "distance_f": "12",
              "distance_y": "2645",
              "quote": "It's been in the back of our minds for a while to try Enfranchise over a mile and a half. She's often found herself a bit far back over a mile and a quarter. The extra couple of furlongs has suited her well and she's a likeable, consistent filly - Charlie Johnston, joint-trainer."
            },
            {
              "date": "2022-01-28",
              "horse": "Enfranchise",
              "horse_id": "hrs_24456236",
              "race": "Play 4 To Win At Betway Handicap",
              "race_id": "rac_10420462",
              "course": "Lingfield (AW)",
              "course_id": "crs_10218",
              "distance_f": "10",
              "distance_y": "2200",
              "quote": "It's great she's come out six days after a career-best performance in the Winter Oaks last time, in which she was a little bit unlucky. I just had to be patient today and wait for the gaps but Enfranchise quickened up well. I won on her over a mile and she was doing her best work at the end. I thought this trip would suit and she could stay further - Andrew Breslin, jockey."
            }
          ],
