          "comment": "Best run this year came last time at the Curragh; a repeat of that would make him a player",
          "spotlight": "Has won four times at 1m; last win came in a Dundalk handicap in October off a mark of 90; best run this year came last time when a 3l third of 15 at the Curragh (7f, good); a neck behind Exquisite Acclaim on that occasion; retains the same mark and a repeat of that run would put him in the thick of things.",
          "quotes": [
            {
              "date": "2023-07-02",
              "horse": "Blues Emperor",
              "horse_id": "hrs_27861617",
              "race": "Dubai Duty Free Derby Festival Handicap (Premier Handicap)",
              "race_id": "rac_10971480",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "Blues Emperor is very brave and when he gets his head in front he is hard to get past."
            },
            {
              "date": "2023-05-21",
              "horse": "Blues Emperor",
              "horse_id": "hrs_27861617",
              "race": "Tote Always SP Or Better Handicap",
              "race_id": "rac_10939435",
              "course": "Naas",
              "course_id": "crs_4992",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "Blues Emperor is a bonny little horse. We wondered would he handle this better ground but he is very tough and genuine. Hopefully he will make into a Premier Handicap horse - Johnny Murtagh, trainer."
            },
            {
              "date": "2022-09-22",
              "horse": "Blues Emperor",
              "horse_id": "hrs_27861617",
              "race": "MAC Fuels & General Supplies Maiden",
              "race_id": "rac_10684869",
              "course": "Listowel",
              "course_id": "crs_4940",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "Blues Emperor has probably done nothing but improve. He ran well at Dundalk and very well at Cork the last day. Ben (Coen) said he got into a pocket but he's very genuine, he tried his hardest when he got into the gap. We'll probably give him one more outing this season - Johnny Murtagh, trainer."
            }
          ],
