          "comment": "Finished a neck ahead of Blues Emperor last time; below his best this term but good chance",
          "spotlight": "Finished a neck in front of Blues Emperor at the Curragh last time (7f, good); six of his seven wins have come on the AW; sole win on turf was at Gowran last August from a 2lb higher mark (7f, good to firm); below his best this term but has a good chance here.",
          "quotes": [
            {
              "date": "2025-01-17",
              "horse": "Exquisite Acclaim",
              "horse_id": "hrs_24907491",
              "race": "Group Deals Available At Dundalk Stadium Rated Race",
              "race_id": "rac_11518169",
              "course": "Dundalk (AW)",
              "course_id": "crs_29588",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Exquisite Acclaim travelled everywhere, was half-idling with me up the straight and I brought him over towards the rail. Once he did that he ran through the line well - Jamie Powell, jockey."
            },
            {
              "date": "2024-03-22",
              "horse": "Exquisite Acclaim",
              "horse_id": "hrs_24907491",
              "race": "Sky Bet Acca Freeze Handicap",
              "race_id": "rac_11229283",
              "course": "Dundalk (AW)",
              "course_id": "crs_29588",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "Exquisite Acclaim has come back down now and he has got confidence. He's tough and he's hardy, and he's really putting his head down. He has a bit of class to him - Ado McGuinness, trainer."
            },
            {
              "date": "2021-09-17",
              "horse": "Exquisite Acclaim",
              "horse_id": "hrs_24907491",
              "race": "Irish EBF Median Sires Series Maiden (IRE Incentive Race)",
              "race_id": "rac_10314122",
              "course": "Dundalk (AW)",
              "course_id": "crs_29588",
              "distance_f": "6",
              "distance_y": "1320",
              "quote": "Exquisite Acclaim was good. He was giving weight to all rivals and still picked them up well. We've always held him in high regard at home and didn't think he'd have to wait until now to win his maiden, but he could be a nice progressive three-year-old next year - Shane Foley, rider."
            }
          ],
          "stable_tour": [
            {
              "quote": "I was very pleased with him when fourth in the 2,000 Guineas Trial at Leopardstown. He might not be a top horse but is going the right way and could well be a nice Listed type. 14-04-22"
            }
          ],
