          "comment": "Sole win was a maiden on this card last year; can't be ruled out",
          "spotlight": "Behind two of today's rivals at the Curragh last time, plugging on into seventh (7f, good); sole win came over this C&D in a maiden on this card last year (7f, good); good run at Gowran on penultimate run when sporting a first-time hood and beaten a neck into second (7f, soft); can't be ruled out.",
          "quotes": [
            {
              "date": "2024-07-10",
              "horse": "Four Blondes",
              "horse_id": "hrs_36387379",
              "race": "Irish Stallion Farms EBF Maiden",
              "race_id": "rac_11340823",
              "course": "Fairyhouse",
              "course_id": "crs_4732",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Four Blondes deserved that on last year's form. She's by Gleneagles and wouldn't mind a little bit more ease in the ground. She's out of a six-time winning Exceed And Excel mare but seven furlongs to a mile would be fine. She can be a little bit saucy and has a little bit of a funny head carriage but she could be progressive - Ross O'Sullivan, trainer"
            }
          ],
          "stable_tour": [
            {
              "quote": "There's a fillies' handicap over 7f at Fairyhouse coming up which should really suit her, as she won her maiden around there. She was just collared close home at Gowran the other night. She just had to use up a bit too much petrol early there and it cost her. 11-09-24"
            }
          ],
