          "comment": "Narrow winner last time; won off 1lb higher mark last year; can go well again",
          "spotlight": "Built on a good third over 6.5f at Listowel last month to run out a narrow winner at Limerick ten days later (1m, good); raised 3lb for that win but won off a 1lb higher mark over this trip at Naas last year; can go well again.",
          "quotes": [
            {
              "date": "2023-10-14",
              "horse": "Facethepuckout",
              "horse_id": "hrs_13974583",
              "race": "Oktoberfest Weekend Handicap",
              "race_id": "rac_11071944",
              "course": "Naas",
              "course_id": "crs_4992",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Facethepuckout has been consistent all year and been placed five times. That's his ground. The race just worked out for him as they have gone a real good gallop which he needs over seven. Leigh rode him for luck and it's worked out - Michael O'Callaghan, trainer"
            },
            {
              "date": "2022-10-18",
              "horse": "Facethepuckout",
              "horse_id": "hrs_13974583",
              "race": "Racing Club Membership Handicap (Div II)",
              "race_id": "rac_10716433",
              "course": "Gowran Park",
              "course_id": "crs_4784",
              "distance_f": "8.5",
              "distance_y": "1835",
              "quote": "Facethepuckout came out of the Curragh race well. He's just sweet and in a good vein of form at the minute. He's well handicapped on his old form but chances are the handicapper will catch up with him - Michael O'Callaghan, trainer."
            },
            {
              "date": "2019-09-11",
              "horse": "Facethepuckout",
              "horse_id": "hrs_13974583",
              "race": "Listowel Arms Handicap",
              "race_id": "rac_9614761",
              "course": "Listowel",
              "course_id": "crs_4940",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Facethepuckout was bought as a fun horse. He has sweetened up lovely and looked a different horse today. He's fit and well and went through the ground - Michael O'Callaghan, trainer."
            },
            {
              "date": "2018-08-15",
              "horse": "Facethepuckout",
              "horse_id": "hrs_13974583",
              "race": "Derek Ryan Live After Racing Nursery Handicap (Plus 10 Race)",
              "race_id": "rac_9222512",
              "course": "Gowran Park",
              "course_id": "crs_4784",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Donnacha [O'Brien] gave him a nice ride and on his Galway run he was entitled to be thereabouts. He'd probably be okay going a mile as well. He'll go for another nursery and I think there is more progression to come from him - Joseph O'Brien, trainer"
            }
          ],
