          "comment": "Winner in May off 70; run last time was encouraging; can be involved with 7lb claimer",
          "spotlight": "Cork apprentice handicap winner in May (1m, good) off 2lb lower; three runs following that were not at the same level, albeit his run at the Curragh last time in first-time cheekpieces was encouraging (1m, good); blinkers are now reapplied having been tried previously; claimer's allowance should make him competitive.",
